CREATE TABLE favorite_words (
 user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
 word_id UUID NOT NULL REFERENCES words(id) ON DELETE CASCADE,
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,word_id)
);
CREATE TABLE verbs (
 id UUID PRIMARY KEY, arabic VARCHAR(255) NOT NULL, normalized VARCHAR(255) NOT NULL, dutch VARCHAR(255) NOT NULL, root VARCHAR(30) NOT NULL, pattern VARCHAR(30) NOT NULL, verification_status VARCHAR(30) NOT NULL
);
CREATE TABLE verb_forms (
 id UUID PRIMARY KEY, verb_id UUID NOT NULL REFERENCES verbs(id) ON DELETE CASCADE, category VARCHAR(30) NOT NULL, pronoun VARCHAR(50), form VARCHAR(255) NOT NULL, position INTEGER NOT NULL, UNIQUE(verb_id,category,position)
);
